    for(String token : tokens) {

        if(esNumero(token)) {
            pila.push(Double.parseDouble(token));
        }
        else {

            double b = pila.pop();
            double a = pila.pop();

            switch(token) {

                case "+":
                    pila.push(a + b);
                    break;

                case "-":
                    pila.push(a - b);
                    break;

                case "*":
                    pila.push(a * b);
                    break;

                case "/":
                    pila.push(a / b);
                    break;
            }
        }
    }

    System.out.println("\nResultado = " + pila.pop());
}
